# Brass's Bounty (FDN): "For each land you control, create a Treasure token."
# CREATE_TOKEN with M21 Gadrak's verified Treasure TokenSpec (byte for byte); "a ... token for each
# land you control" is "N for each X" = QBin(MUL, QConst(1), QCount(lands you control)) (the
# MAPPER_GUIDE form; ZNR Squad Commander's "a ... token for each creature in your party").
treasure = TokenSpec(
    name='Treasure',
    type_line='Artifact',
    types=('Artifact',),
    subtypes=(),
    power=None,
    toughness=None,
    keywords=(Keyword.TREASURE,),
    abilities=(
        ActivatedAbility(
            cost=Cost(
                parts=(
                    CostSacrifice(
                        target=Selector(
                            count=QConst(value=1),
                            mode=SelectorMode.CHOOSE,
                            filter=FAtom(pred=FAtomPred.IS_SOURCE),
                            zones=(Zone(kind=ZoneKind.BATTLEFIELD, controller=ControllerRef.ANY),),
                        ),
                    ),
                    CostTap(),
                ),
            ),
            effect=A(Verb.ADD_MANA, {
                'amount': QConst(value=1),
                'color': 'ANY',
                'controller': ControllerRef.YOU,
            }),
        ),
    ),
)
abilities = [
    SpellAbility(
        kind=SpellKind.SORCERY,
        effect=A(Verb.CREATE_TOKEN, {
            'count': QBin(
                op=QBinOp.MUL,
                left=QConst(value=1),
                right=QCount(
                    selector=Selector(
                        count=QUnbounded(),
                        mode=SelectorMode.ALL,
                        filter=FAnd(
                            children=(
                                FAtom(pred=FAtomPred.CONTROLLER_IS, who=ControllerRef.YOU),
                                FAtom(pred=FAtomPred.TYPE_EQ, string_value='Land'),
                            ),
                        ),
                        zones=(Zone(kind=ZoneKind.BATTLEFIELD, controller=ControllerRef.ANY),),
                    ),
                ),
            ),
            'tokens': treasure,
        }),
    ),
]
